CREATE OR REPLACE FUNCTION public.username_available(_username text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT _username ~ '^[a-z0-9_]{3,30}$' AND NOT EXISTS (SELECT 1 FROM public.profiles WHERE username=lower(trim(_username))); $$;
REVOKE ALL ON FUNCTION public.username_available(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.username_available(text) TO anon, authenticated, service_role;